import{_ as a,o as s,c as n,a2 as t}from"./chunks/framework.doxMM-x8.js";const u=JSON.parse('{"title":"Project Structure","description":"","frontmatter":{"docLocale":"en","counterpart":"/architecture/project-structure","contentType":"concept","prev":false,"next":{"text":"Module boundaries","link":"/en/architecture/module-boundaries"}},"headers":[],"relativePath":"en/architecture/project-structure.md","filePath":"en/architecture/project-structure.md"}'),r={name:"en/architecture/project-structure.md"};function o(i,e,c,p,l,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h1><p>Before changing Lab Word, distinguish the application, shared capabilities and isolated preview. Lab Viewer and the session-local Asset Library are integrated. Foundation V1&#39;s persistent world and server-owned devices continue through the published implementation tickets.</p><h2 id="source-map" tabindex="-1">Source Map <a class="header-anchor" href="#source-map" aria-label="Permalink to &quot;Source Map&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apps/</span></span>
<span class="line"><span>  web/src/app-examples.tsx  Explicit business composition</span></span>
<span class="line"><span>  web/src/router.tsx        Web routing adapter</span></span>
<span class="line"><span>  api/src/lib.rs            HTTP Router and OpenAPI composition</span></span>
<span class="line"><span>  worker/src/main.rs        Background handlers and maintenance</span></span>
<span class="line"><span>  desktop/src/              Electron host and IPC</span></span>
<span class="line"><span>  docs/.vitepress/           Bilingual documentation site</span></span>
<span class="line"><span>crates/</span></span>
<span class="line"><span>  app/src/modules/          Identity, membership, jobs, files, knowledge</span></span>
<span class="line"><span>  platform/src/             Database, storage, mail, cache, telemetry</span></span>
<span class="line"><span>packages/</span></span>
<span class="line"><span>  views/src/lab/             Viewer, session-local catalog and Lab contribution</span></span>
<span class="line"><span>  views/src/shell/           Universal shell and composition contracts</span></span>
<span class="line"><span>  views/src/knowledge/       Knowledge views</span></span>
<span class="line"><span>  ui/src/                   Shared components and styles</span></span>
<span class="line"><span>  contracts/                Rust-generated API contracts</span></span>
<span class="line"><span>  sdk/                      Generated client</span></span>
<span class="line"><span>migrations/                 Explicit SQL migrations</span></span>
<span class="line"><span>scripts/                    Development, checks, builds, operations</span></span>
<span class="line"><span>docs/                       Content, ADRs and plans</span></span></code></pre></div><p>See the <a href="./../guides/lab-viewer">viewer guide</a> for the current application. The accepted Foundation v1 preview is preserved on the separate <code>preview/lab-foundation-v1</code> branch; the <a href="https://github.com/CaiZongyuan/labworld/blob/fece778cddb1db85f432c0c64672617a447317be/docs/handoffs/digital-twin-foundation-v1.md" target="_blank" rel="noreferrer">developer handoff</a> explains how to obtain and run it. It is outside the production build.</p><h2 id="lab-integration-points" tabindex="-1">Lab Integration Points <a class="header-anchor" href="#lab-integration-points" aria-label="Permalink to &quot;Lab Integration Points&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/labworld/blob/fece778cddb1db85f432c0c64672617a447317be/apps/web/src/app-examples.tsx" target="_blank" rel="noreferrer">assembly point</a>consumes business contributions; the <a href="https://github.com/CaiZongyuan/labworld/blob/fece778cddb1db85f432c0c64672617a447317be/apps/web/src/router.tsx" target="_blank" rel="noreferrer">routing adapter</a>connects them to the host. <a href="https://github.com/CaiZongyuan/labworld/blob/fece778cddb1db85f432c0c64672617a447317be/packages/views/src/shell/app-contract.ts" target="_blank" rel="noreferrer">app-contract.ts</a>declares contributions and <a href="https://github.com/CaiZongyuan/labworld/blob/fece778cddb1db85f432c0c64672617a447317be/packages/views/src/shell/app-contract.ts" target="_blank" rel="noreferrer">app-contract.ts</a>validates composition.</p><p>Model import, the 3D viewport and asset information belong to Lab. The universal shell does not know equipment. Lab contributes <code>/lab</code> and <code>/assets</code>, and composition selects Lab after authentication; direct access to <code>/</code> keeps the universal home. Existing pages and 3D code are lazy-loaded. Foundation work must preserve these responsibilities.</p><h2 id="check-boundaries" tabindex="-1">Check Boundaries <a class="header-anchor" href="#check-boundaries" aria-label="Permalink to &quot;Check Boundaries&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p>Run from the repository root. Boundary checks inspect package dependencies, Rust table ownership and infrastructure imports in pure Domain code. They do not provide complete example addition/removal tooling. See <a href="./../testing/feedback-loop">development and validation</a>for source, behavior and permission checks.</p><p>Next, read <a href="./module-boundaries">module boundaries</a>, then implement the accepted Lab experience.</p><hr><p>Source version：<code>fece778cddb1</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/fece778cddb1db85f432c0c64672617a447317be/docs/architecture/project-structure.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,14)])])}const b=a(r,[["render",o]]);export{u as __pageData,b as default};
